def eval_expr(s: str) -> int:
    """Evaluate an arithmetic expression with non-negative integer literals, + - * /, parentheses, spaces and unary minus.
Usual precedence; * and / are left-associative; / is integer division truncating toward zero (like C).
Example: eval_expr("2*(3+4) - -6/4") == 15
    """
    import re

    tokens = re.findall(r'\d+|[+\-*/()]', s.replace(' ', ''))
    pos = 0

    def parse_expr():
        nonlocal pos
        val = parse_term()
        while pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            rhs = parse_term()
            if op == '+':
                val += rhs
            else:
                val -= rhs
        return val

    def parse_term():
        nonlocal pos
        val = parse_factor()
        while pos < len(tokens) and tokens[pos] in ('*', '/'):
            op = tokens[pos]
            pos += 1
            rhs = parse_factor()
            if op == '*':
                val *= rhs
            else:
                val = int(val / rhs)
        return val

    def parse_factor():
        nonlocal pos
        if tokens[pos] == '-':
            pos += 1
            return -parse_factor()
        if tokens[pos] == '+':
            pos += 1
            return parse_factor()
        if tokens[pos] == '(':
            pos += 1
            val = parse_expr()
            pos += 1  # skip ')'
            return val
        return int(tokens[pos])

    return parse_expr()
