import heapq

def dijkstra(n: int, edges: list, src: int) -> list:
    """Directed graph with nodes 0..n-1 and edges (u, v, w), w >= 0. Return a list of shortest distances from src;
use -1 for unreachable nodes.
    """
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    dist = [-1] * n
    dist[src] = 0
    heap = [(0, src)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            nd = d + w
            if dist[v] == -1 or nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return dist
