def lis_length(nums: list) -> int:
    """Length of the longest strictly increasing subsequence. Must run in O(n log n) for n up to 200000.
    """
    import bisect

    tails = []
    for x in nums:
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)
