def word_break_all(s: str, words: list) -> list:
    """Return all ways to split s into a sequence of dictionary words (words may be reused), each as a space-joined
string, sorted lexicographically.
    """
    word_set = set(words)
    results = []

    def backtrack(start: int, current: list):
        if start == len(s):
            results.append(" ".join(current))
            return
        for prefix_len in range(1, len(s) - start + 1):
            candidate = s[start:start + prefix_len]
            if candidate in word_set:
                current.append(candidate)
                backtrack(start + prefix_len, current)
                current.pop()

    backtrack(0, [])
    return sorted(results)
