def regex_match(s: str, p: str) -> bool:
    """Full-string match of s against pattern p supporting '.' (any single char) and '*' (zero or more of the preceding
element).
    """
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(i: int, j: int) -> bool:
        # i indexes into s, j indexes into p
        if j == len(p):
            return i == len(s)
        first = i < len(s) and (p[j] == s[i] or p[j] == '.')
        if j + 1 < len(p) and p[j + 1] == '*':
            # skip the "x*" pair entirely (zero occurrences), or consume one char if it matches
            return dp(i, j + 2) or (first and dp(i + 1, j))
        return first and dp(i + 1, j + 1)

    return dp(0, 0)
