def min_window(s: str, t: str) -> str:
    """Smallest substring of s containing every character of t with multiplicity. If several have the minimum length,
return the leftmost. Return "" if none.
    """
    if not t or not s or len(s) < len(t):
        return ""

    need = {}
    for ch in t:
        need[ch] = need.get(ch, 0) + 1

    required = len(need)
    formed = 0

    window_counts = {}
    best_len = len(s) + 1
    best_start = 0
    left = 0

    for right, ch in enumerate(s):
        if ch in need:
            window_counts[ch] = window_counts.get(ch, 0) + 1
            if window_counts[ch] == need[ch]:
                formed += 1

        # Try to shrink the window from the left while it's still valid
        while formed == required and left <= right:
            window_len = right - left + 1
            if window_len < best_len:
                best_len = window_len
                best_start = left

            left_ch = s[left]
            if left_ch in need:
                window_counts[left_ch] -= 1
                if window_counts[left_ch] < need[left_ch]:
                    formed -= 1
            left += 1

    if best_len > len(s):
        return ""
    return s[best_start:best_start + best_len]
