def flatten_dict(d: dict, sep: str = '.') -> dict:
    """Flatten nested dicts: {'a': {'b': 1, 'c': {'d': 2}}, 'e': 3} -> {'a.b': 1, 'a.c.d': 2, 'e': 3}.
Empty nested dicts are dropped. Non-dict values (including lists) are kept as-is.
    """
    result = {}
    for key, value in d.items():
        if isinstance(value, dict) and value:
            nested = flatten_dict(value, sep)
            for nested_key, nested_value in nested.items():
                result[f"{key}{sep}{nested_key}"] = nested_value
        elif isinstance(value, dict) and not value:
            # Empty dict: dropped
            continue
        else:
            result[key] = value
    return result
